import React, { useState } from 'react';

const BankTransferDetails = ({ onFileChange }) => {
    const [selectedFile, setSelectedFile] = useState(null);
    const [isDragOver, setIsDragOver] = useState(false);

    const handleFileSelect = (file) => {
        if (!file) return;
        // Basic validation
        if (file.size > 5 * 1024 * 1024) {
            alert('File size must be less than 5MB');
            return;
        }
        setSelectedFile(file);
        onFileChange(file); // Lift the file up to the parent
    };

    const handleFileRemove = () => {
        setSelectedFile(null);
        onFileChange(null);
    };

    const handleDrop = (e) => {
        e.preventDefault();
        setIsDragOver(false);
        if (e.dataTransfer.files && e.dataTransfer.files[0]) {
            handleFileSelect(e.dataTransfer.files[0]);
        }
    };

    return (
        <div className="form-section">
            <h2 className="section-title">Bank Transfer Details</h2>
            <div className="bank-details">
                {/* Bank Info Table would go here */}
                <p style={{textAlign: 'center', marginBottom: '1rem'}}>Please make your payment to the account details below.</p>

                <div className="upload-section">
                    <h3 style={{ marginBottom: '1rem' }}>Upload Transfer Slip</h3>
                    <input
                        type="file"
                        id="transfer-slip"
                        className="file-input"
                        accept=".jpg,.jpeg,.png,.pdf"
                        onChange={(e) => handleFileSelect(e.target.files[0])}
                    />
                    <div
                        className={`upload-area ${isDragOver ? 'dragover' : ''}`}
                        onClick={() => document.getElementById('transfer-slip').click()}
                        onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}
                        onDragLeave={() => setIsDragOver(false)}
                        onDrop={handleDrop}
                    >
                        <div className="upload-icon">📎</div>
                        <div className="upload-text">Click to upload or drag and drop</div>
                        <div className="file-types">JPG, PNG, PDF (Max 5MB)</div>
                    </div>
                    {selectedFile && (
                        <div className="selected-file" style={{ display: 'flex' }}>
                            <span className="file-name">{selectedFile.name}</span>
                            <button type="button" className="remove-file" onClick={handleFileRemove}>×</button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default BankTransferDetails;
